            var A = BuildDiag1x1(ref arena, (float)4, (float)0);   // A[1,1] == 0 -> not SPD
            Assert.Throws<ArgumentException>(() => { var m = arena.floatChebyshev(in A); });
        }
        finally { arena.Dispose(); }
    }

